import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/modifiers/strobe/strobe_modifier.dart';
import '../macro_editor_node_module.dart';

final class StrobeMacroEditorNodeModule extends MacroEditorNodeModule {
  @override
  String get kind => strobeModifierKind;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.strobe',
      moduleKind: strobeModifierKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.flash_on_outlined,
      title: 'Strobe',
      subtitle: 'Gate → brightness flash',
    ),
  ];

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => _nodeWithConfiguration(
    MacroNode(
      id: newId(),
      kind: kind,
      displayName: 'Strobe',
      ports: const <MacroPortDeclaration>[],
    ),
    StrobeModifierConfiguration(),
  );

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration = StrobeModifierConfiguration.fromNodeParameters(
        nodeContext.node.parameters,
      );
      return MacroEditorNodeInspectorCard(
        icon: Icons.flash_on_outlined,
        title: titleFor(nodeContext.node),
        enabled: nodeContext.state.enabled,
        onRemove: nodeContext.removeNode,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            TextFormField(
              key: ValueKey<String>(
                'strobe-duration-${nodeContext.node.id}-${configuration.flashDuration.inMilliseconds}',
              ),
              initialValue: configuration.flashDuration.inMilliseconds
                  .toString(),
              enabled: nodeContext.state.enabled,
              keyboardType: TextInputType.number,
              inputFormatters: <TextInputFormatter>[
                FilteringTextInputFormatter.digitsOnly,
              ],
              decoration: const InputDecoration(
                labelText: 'Flash duration',
                suffixText: 'ms',
                border: OutlineInputBorder(),
              ),
              onChanged: (rawValue) {
                final milliseconds = int.tryParse(rawValue);
                if (milliseconds == null || milliseconds <= 0) return;
                nodeContext.replaceNode(
                  _nodeWithConfiguration(
                    nodeContext.node,
                    StrobeModifierConfiguration(
                      flashDuration: Duration(milliseconds: milliseconds),
                    ),
                  ),
                );
              },
            ),
            const SizedBox(height: 8),
            const Text(
              'True запускає один спалах: 1 → 0. Новий спалах можливий після false → true.',
            ),
          ],
        ),
      );
    } on FormatException catch (error) {
      return MacroEditorNodeErrorCard(
        message: 'Strobe configuration needs repair: $error',
      );
    }
  }

  MacroNode _nodeWithConfiguration(
    MacroNode node,
    StrobeModifierConfiguration configuration,
  ) => node.copyWith(
    parameters: configuration.toNodeParameters(),
    ports: StrobeModifierFactory.portsForNode(node.id),
  );
}
